package sigstore

import (
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/hex"
	"encoding/pem"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// Synthetic: keys generated by the test.

func pemOf(t *testing.T, pub any) ([]byte, []byte) {
	der, err := x509.MarshalPKIXPublicKey(pub)
	require.NoError(t, err)
	return pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der}), der
}

func TestLoadPublicKey_Kinds(t *testing.T) {
	ec, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	edPub, _, err := ed25519.GenerateKey(rand.Reader)
	require.NoError(t, err)
	rsa2048, err := rsa.GenerateKey(rand.Reader, 2048)
	require.NoError(t, err)
	for name, pub := range map[string]any{"ecdsa-p256": &ec.PublicKey, "ed25519": edPub, "rsa-2048": &rsa2048.PublicKey} {
		p, der := pemOf(t, pub)
		_, fp, err := LoadPublicKey(p)
		require.NoError(t, err, name)
		sum := sha256.Sum256(der)
		assert.Equal(t, "sha256:"+hex.EncodeToString(sum[:]), fp, name)
	}
}

func TestLoadPublicKey_RejectsWeakRSA(t *testing.T) {
	k, err := rsa.GenerateKey(rand.Reader, 1024)
	require.NoError(t, err)
	p, _ := pemOf(t, &k.PublicKey)
	_, _, err = LoadPublicKey(p)
	assert.ErrorContains(t, err, "too weak")
}

func TestLoadPublicKey_RejectsP224(t *testing.T) {
	k, err := ecdsa.GenerateKey(elliptic.P224(), rand.Reader)
	require.NoError(t, err)
	p, _ := pemOf(t, &k.PublicKey)
	_, _, err = LoadPublicKey(p)
	assert.Error(t, err)
}

func TestLoadPublicKey_NotPEM(t *testing.T) {
	_, _, err := LoadPublicKey([]byte("not a key"))
	assert.Error(t, err)
}

func TestNormalizeFingerprint(t *testing.T) {
	sum := sha256.Sum256([]byte("k"))
	want := "sha256:" + hex.EncodeToString(sum[:])
	assert.Equal(t, want, normalizeFingerprint(want))
	assert.Equal(t, want, normalizeFingerprint(hex.EncodeToString(sum[:])))
	assert.Equal(t, want, normalizeFingerprint(base64.StdEncoding.EncodeToString(sum[:])))
	assert.Equal(t, "", normalizeFingerprint("abcd"))
	assert.Equal(t, "", normalizeFingerprint(""))
}

func TestLoadPublicKeys_Concatenated(t *testing.T) {
	a, _ := pemOf(t, &mustEC(t).PublicKey)
	b, _ := pemOf(t, &mustEC(t).PublicKey)
	keys, err := LoadPublicKeys(append(a, b...))
	require.NoError(t, err)
	assert.Len(t, keys, 2)
	_, err = LoadPublicKeys([]byte("garbage"))
	assert.Error(t, err)
}

func mustEC(t *testing.T) *ecdsa.PrivateKey {
	k, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	return k
}
